class Solution {
public:
    int countComponents(int n, vector<vector<int>>& edges) {
        vector<int> parent(n);
        iota(parent.begin(), parent.end(), 0);
        int count = n;
        function<int(int)> find = [&](int x) {
            return parent[x] == x ? x : parent[x] = find(parent[x]);
        };
        for (const auto& e : edges) {
            int ru = find(e[0]), rv = find(e[1]);
            if (ru != rv) {
                parent[ru] = rv;
                count--;
            }
        }
        return count;
    }
};

