var countComponents = function(n, edges) {
    const parent = Array.from({ length: n }, (_, i) => i);
    let count = n;
    function find(x) {
        return parent[x] === x ? x : (parent[x] = find(parent[x]));
    }
    for (const [u, v] of edges) {
        const ru = find(u), rv = find(v);
        if (ru !== rv) {
            parent[ru] = rv;
            count--;
        }
    }
    return count;
};
